package com.cyancoder.tenant.service;import java.nio.charset.StandardCharsets;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpHeaders;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component public class NotificationInvitationClient{private final RestClient client;private final String auth;private final String acceptBaseUrl;public NotificationInvitationClient(RestClient.Builder builder,@Value("${notification.service.base-url:http://localhost:9122}")String base,@Value("${notification.service.internal.username:notification_internal}")String user,@Value("${notification.service.internal.password:notification_secret}")String pass,@Value("${tenant.invitation.accept-base-url:http://localhost:3000/auth/invitation}")String acceptBaseUrl){client=builder.baseUrl(base).build();auth="Basic "+Base64.getEncoder().encodeToString((user+":"+pass).getBytes(StandardCharsets.UTF_8));this.acceptBaseUrl=acceptBaseUrl;}
 public String send(String tenant,String invitationId,String email,String rawToken,java.time.Instant expires){try{Map<?,?> response=client.post().uri("/internal/notifications/send").header(HttpHeaders.AUTHORIZATION,auth).body(Map.of("messageKey","tenant-invitation-"+invitationId,"channel","EMAIL","provider","EMAIL","dispatchMode","SYNC","recipient",email,"subject","Workspace invitation","body","You were invited to a Cyan workspace. Accept before "+expires+": "+acceptBaseUrl+"?token="+java.net.URLEncoder.encode(rawToken,StandardCharsets.UTF_8),"model",Map.of("tenantKey",tenant,"expiresAt",expires.toString()),"relatedRef",Map.of("service","tenant-service","invitationId",invitationId))).retrieve().body(Map.class);return response==null?"NOT_CONFIGURED":Objects.toString(response.get("status"),"NOT_CONFIGURED");}catch(RuntimeException e){return"NOT_CONFIGURED";}}
}
